<?php session_start(); require_once __DIR__.'/../config/database.php'; require_role('student'); $data=db_load(); $uid=(int)$_SESSION['user_id']; $user=db_user($data,$uid); $student=db_student_by_user($data,$uid); $message='';$messageType='success'; if($_SERVER['REQUEST_METHOD']==='POST'){$phone=trim($_POST['phone']??'');$college=trim($_POST['college']??'');$course=trim($_POST['course']??'');$skills=trim($_POST['skills']??'');$bio=trim($_POST['bio']??'');$resume=$student['resume']??'';if(isset($_FILES['resume'])&&$_FILES['resume']['error']!==UPLOAD_ERR_NO_FILE){if($_FILES['resume']['error']!==UPLOAD_ERR_OK){$message='Resume upload failed.';$messageType='error';}elseif(strtolower(pathinfo($_FILES['resume']['name'],PATHINFO_EXTENSION))!=='pdf'){$message='Resume must be a PDF file.';$messageType='error';}elseif($_FILES['resume']['size']>5*1024*1024){$message='Resume must be smaller than 5 MB.';$messageType='error';}else{$dir=__DIR__.'/../uploads';if(!is_dir($dir))@mkdir($dir,0775,true);$file='resume_'.$uid.'_'.time().'.pdf';if(move_uploaded_file($_FILES['resume']['tmp_name'],$dir.'/'.$file))$resume=$file;else{$message='Unable to save the resume.';$messageType='error';}}}if($messageType==='success'){$updated=false;foreach($data['students'] as &$s){if((int)$s['user_id']===$uid){$s['phone']=$phone;$s['college']=$college;$s['course']=$course;$s['skills']=$skills;$s['bio']=$bio;$s['resume']=$resume;$updated=true;break;}}unset($s);if($updated&&db_save($data)){$message='Profile updated successfully.';$student=db_student_by_user($data,$uid);}else{$message='Unable to update your profile.';$messageType='error';}}} ?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profile · Arti Vaniyar Internships Hub</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include 'student_nav.php'; ?><main class="dashboard narrow"><div class="page-heading"><div><p class="eyebrow">YOUR PROFILE</p><h1>Make your profile count.</h1><p>Strong profiles make it easier for companies to understand your skills.</p></div></div><?php if($message): ?><div class="alert <?=$messageType==='success'?'success':'error'?>"><?=e($message)?></div><?php endif; ?><div class="form-card"><form method="POST" enctype="multipart/form-data"><div class="form-grid"><div><label>Name</label><input value="<?=e($user['name']??'')?>" disabled></div><div><label>Email</label><input value="<?=e($user['email']??'')?>" disabled></div><div><label>Phone</label><input name="phone" value="<?=e($student['phone']??'')?>" placeholder="+91..."></div><div><label>College</label><input name="college" value="<?=e($student['college']??'')?>" placeholder="College / University"></div><div><label>Course</label><input name="course" value="<?=e($student['course']??'')?>" placeholder="B.E. Computer Science"></div><div><label>Skills</label><input name="skills" value="<?=e($student['skills']??'')?>" placeholder="PHP, JavaScript, MySQL"></div></div><label>About you</label><textarea name="bio" rows="5" placeholder="A short introduction..."><?=e($student['bio']??'')?></textarea><label>Resume (PDF, max 5 MB)</label><input type="file" name="resume" accept="application/pdf,.pdf"><?php if(!empty($student['resume'])):?><p class="small-text">Resume uploaded: <?=e($student['resume'])?></p><?php endif; ?><button class="btn primary" type="submit">Save profile</button></form></div></main></body></html>
